import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"租来的车","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/08-rented-car.md","filePath":"zh/more/maltese/practice/dialogues/08-rented-car.md"}'),e={name:"zh/more/maltese/practice/dialogues/08-rented-car.md"},i=r('<h1 id="租来的车" tabindex="-1">租来的车 <a class="header-anchor" href="#租来的车" aria-label="Permalink to &quot;租来的车&quot;">​</a></h1><p><strong>场景：</strong> Carmen Micallef 打电话给租车公司，要找 Martin Deguara 先生。对方不在，她向职员说明她十五天前租了车、现在周五要飞回自己的国家；双方商定她周五进机场前到位于机场停车场的办公室还车、检查车辆并退还 VISA 押金。</p><p><strong>来源：</strong> 对话改编自 Charles Daniel Saliba 的《Speaking Maltese 2》（Djalogu addattat minn Speaking Maltese 2 ta&#39; Charles Daniel Saliba）</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>Carmen（客户）：</strong> Bonġu, jien Carmen Micallef. Nista&#39; nkellem lis-Sur Martin Deguara, jekk jogħġbok?</p><p><strong>Tal-karozzi（租车公司职员）：</strong> Skużani, illum Martin mhux hawn. Nista&#39; naqdik jien?</p><p><strong>Carmen（客户）：</strong> Ma jimpurtax, mela ħa nispjega kollox lilek. Ħmistax ilu kont krejt karozza mingħandkom u issa se nsiefer lura pajjiżi nhar il-Ġimgħa. Nixtieq inkun naf kif se ngħaddilkom il-karozza lura.</p><p><strong>Tal-karozzi（租车公司职员）：</strong> Inti x&#39;ħin se ssiefer il-Ġimgħa?</p><p><strong>Carmen（客户）：</strong> It-titjira hija fid-disgħa ta&#39; billejl.</p><p><strong>Tal-karozzi（租车公司职员）：</strong> Tajjeb ħafna, mela l-Ġimgħa stess qabel tidħol l-ajruport ejja hawn l-uffiċċju tagħna li jinsab fil-parkeġġ tal-ajruport stess. Ikollna bżonn nispezzjonaw il-karozza u malli jkun kollox sew, nirrilaxxaw il-VISA tiegħek.</p><p><strong>Carmen（客户）：</strong> Ok, naħseb ikunu xi s-sitta ta&#39; flgħaxija kif nasal.</p><p><strong>Tal-karozzi（租车公司职员）：</strong> Tajjeb, ikun hawn jien dak il-ħin.</p><p><strong>Carmen（客户）：</strong> Sewwa wisq, mela narak il-Ġimgħa fis-sitta ta&#39; flgħaxija. Grazzi!</p><p><strong>Tal-karozzi（租车公司职员）：</strong> Grazzi lilek, saħħa!</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-carmen-客户" tabindex="-1">1. Carmen（客户） <a class="header-anchor" href="#_1-carmen-客户" aria-label="Permalink to &quot;1. Carmen（客户）&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu, jien Carmen Micallef. Nista&#39; nkellem lis-Sur Martin Deguara, jekk jogħġbok?</p><p><strong>整句：</strong> 早上好，我是 Carmen Micallef。请问我能和 Martin Deguara 先生说话吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Bonġu</td><td>早上好</td><td>正式问候语</td></tr><tr><td>jien</td><td>我</td><td>第一人称代词</td></tr><tr><td>Carmen Micallef</td><td>卡门·米卡莱夫</td><td>人名</td></tr><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数</td></tr><tr><td>nkellem</td><td>我和……交谈</td><td>kellem 的第一人称单数</td></tr><tr><td>lis-Sur</td><td>和先生</td><td><code>li</code>+<code>is-Sur</code> 缩合；Sur=先生</td></tr><tr><td>Martin Deguara</td><td>马丁·德瓜拉</td><td>人名</td></tr><tr><td>jekk jogħġbok</td><td>请</td><td>字面&quot;如果你乐意&quot;</td></tr></tbody></table><h3 id="_2-tal-karozzi-租车公司职员" tabindex="-1">2. Tal-karozzi（租车公司职员） <a class="header-anchor" href="#_2-tal-karozzi-租车公司职员" aria-label="Permalink to &quot;2. Tal-karozzi（租车公司职员）&quot;">​</a></h3><p><strong>Malti:</strong> Skużani, illum Martin mhux hawn. Nista&#39; naqdik jien?</p><p><strong>整句：</strong> 抱歉，今天 Martin 不在。我可以为您服务吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Skużani</td><td>请原谅我；抱歉</td><td><code>skuża</code>+<code>-ni</code>（我）</td></tr><tr><td>illum</td><td>今天</td><td>时间副词</td></tr><tr><td>mhux</td><td>不；没有</td><td>否定词</td></tr><tr><td>hawn</td><td>在这里</td><td>地点副词</td></tr><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数</td></tr><tr><td>naqdik</td><td>我为您服务</td><td><code>naqdi</code>+<code>-k</code>（您）</td></tr><tr><td>jien</td><td>我</td><td>强调&quot;我来服务&quot;</td></tr></tbody></table><h3 id="_3-carmen-客户" tabindex="-1">3. Carmen（客户） <a class="header-anchor" href="#_3-carmen-客户" aria-label="Permalink to &quot;3. Carmen（客户）&quot;">​</a></h3><p><strong>Malti:</strong> Ma jimpurtax, mela ħa nispjega kollox lilek. Ħmistax ilu kont krejt karozza mingħandkom u issa se nsiefer lura pajjiżi nhar il-Ġimgħa. Nixtieq inkun naf kif se ngħaddilkom il-karozza lura.</p><p><strong>整句：</strong> 没关系，那我就跟您解释一切吧。十五天前我从你们那里租了一辆车，现在星期五我要飞回我的国家。我想知道该怎么把车还给你们。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ma jimpurtax</td><td>没关系</td><td><code>ma</code>+<code>jimpurta</code>+<code>x</code> 否定</td></tr><tr><td>mela</td><td>那么；那好吧</td><td>语气词</td></tr><tr><td>ħa nispjega</td><td>我来解释</td><td><code>ħa</code>（将要/让我）+nispjega（我解释）</td></tr><tr><td>kollox</td><td>一切</td><td>不定代词</td></tr><tr><td>lilek</td><td>给你；向你说</td><td><code>li</code>+<code>-lek</code></td></tr><tr><td>Ħmistax ilu</td><td>十五天前</td><td>ħmistax（十五）+ilu（……之前）</td></tr><tr><td>kont krejt</td><td>我曾租了</td><td>kont（过去助动词）+krejt（借词 hire/rent，第一人称过去时）</td></tr><tr><td>karozza</td><td>汽车</td><td>阴性名词</td></tr><tr><td>mingħandkom</td><td>从你们那里</td><td><code>mingħand</code>+<code>-kom</code>（你们）</td></tr><tr><td>issa</td><td>现在</td><td>副词</td></tr><tr><td>se nsiefer</td><td>我将飞往</td><td>se（将来标记）+nsiefer（我旅行/飞行）</td></tr><tr><td>lura</td><td>回去；返回</td><td>副词</td></tr><tr><td>pajjiżi</td><td>我的国家</td><td><code>pajjiż</code>+<code>-i</code>（我的）</td></tr><tr><td>nhar</td><td>在……那天</td><td>字面&quot;天&quot;</td></tr><tr><td>il-Ġimgħa</td><td>星期五</td><td>带定冠词</td></tr><tr><td>Nixtieq</td><td>我想要</td><td>第一人称单数</td></tr><tr><td>inkun naf</td><td>想知道</td><td>inkun（我是）+naf（我知道）</td></tr><tr><td>kif</td><td>怎样</td><td>疑问副词</td></tr><tr><td>se ngħaddilkom</td><td>我将交还给你们</td><td><code>ngħaddi</code>（我传递）+-lkom（给你们）</td></tr><tr><td>lura</td><td>归还</td><td>此处作&quot;还回去&quot;</td></tr></tbody></table><h3 id="_4-tal-karozzi-租车公司职员" tabindex="-1">4. Tal-karozzi（租车公司职员） <a class="header-anchor" href="#_4-tal-karozzi-租车公司职员" aria-label="Permalink to &quot;4. Tal-karozzi（租车公司职员）&quot;">​</a></h3><p><strong>Malti:</strong> Inti x&#39;ħin se ssiefer il-Ġimgħa?</p><p><strong>整句：</strong> 您星期五几点出发？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Inti</td><td>你；您</td><td>第二人称代词</td></tr><tr><td>x&#39;ħin</td><td>什么时间</td><td><code>x&#39;</code>（什么）+ħin（时间）</td></tr><tr><td>se ssiefer</td><td>您将出发</td><td>se+ssiefer（第二人称单数）</td></tr><tr><td>il-Ġimgħa</td><td>星期五</td><td>带定冠词</td></tr></tbody></table><h3 id="_5-carmen-客户" tabindex="-1">5. Carmen（客户） <a class="header-anchor" href="#_5-carmen-客户" aria-label="Permalink to &quot;5. Carmen（客户）&quot;">​</a></h3><p><strong>Malti:</strong> It-titjira hija fid-disgħa ta&#39; billejl.</p><p><strong>整句：</strong> 航班是晚上九点。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>It-titjira</td><td>航班</td><td>阴性名词（借词）</td></tr><tr><td>hija</td><td>是</td><td>第三人称阴性单数</td></tr><tr><td>fid-disgħa</td><td>在九点</td><td><code>f&#39;</code>+<code>id-disgħa</code></td></tr><tr><td>ta&#39; billejl</td><td>晚上的</td><td>ta&#39;（的）+billejl（夜晚；规范拼写 <code>bil-lejl</code>）</td></tr></tbody></table><h3 id="_6-tal-karozzi-租车公司职员" tabindex="-1">6. Tal-karozzi（租车公司职员） <a class="header-anchor" href="#_6-tal-karozzi-租车公司职员" aria-label="Permalink to &quot;6. Tal-karozzi（租车公司职员）&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb ħafna, mela l-Ġimgħa stess qabel tidħol l-ajruport ejja hawn l-uffiċċju tagħna li jinsab fil-parkeġġ tal-ajruport stess. Ikollna bżonn nispezzjonaw il-karozza u malli jkun kollox sew, nirrilaxxaw il-VISA tiegħek.</p><p><strong>整句：</strong> 非常好。那就在星期五您进机场之前，来我们的办公室——它就在机场停车场里面。我们需要检查一下车，一旦一切都没问题，我们就退还您的 VISA 押金。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tajjeb ħafna</td><td>非常好</td><td>tajjeb（好）+ħafna（很）</td></tr><tr><td>l-Ġimgħa stess</td><td>就在星期五当天</td><td>stess（本身，加强语）</td></tr><tr><td>qabel</td><td>在……之前</td><td>介词</td></tr><tr><td>tidħol</td><td>您进入</td><td>第二人称单数</td></tr><tr><td>l-ajruport</td><td>机场</td><td>借词 airport</td></tr><tr><td>ejja</td><td>来吧</td><td>祈使语气</td></tr><tr><td>hawn</td><td>这里</td><td>地点副词</td></tr><tr><td>l-uffiċċju</td><td>办公室</td><td>借词 uffiċċju</td></tr><tr><td>tagħna</td><td>我们的</td><td>所有格</td></tr><tr><td>li jinsab</td><td>它位于</td><td>jinsab（位于，第三人称单数）</td></tr><tr><td>fil-parkeġġ</td><td>在停车场</td><td><code>f&#39;</code>+<code>il-parkeġġ</code></td></tr><tr><td>tal-ajruport stess</td><td>机场本身的</td><td>ta&#39;（的）+ajruport+stess</td></tr><tr><td>Ikollna bżonn</td><td>我们将需要</td><td><code>ikollna</code>（我们有）+-bżonn（需要）</td></tr><tr><td>nispezzjonaw</td><td>我们检查</td><td>借词 spezzjona</td></tr><tr><td>il-karozza</td><td>车</td><td>带定冠词</td></tr><tr><td>malli</td><td>一旦</td><td>连词</td></tr><tr><td>jkun kollox sew</td><td>一切顺利</td><td>jkun（是）+kollox（一切）+sew（好）</td></tr><tr><td>nirrilaxxaw</td><td>我们退还；解除</td><td>借词 rilaxxa</td></tr><tr><td>il-VISA tiegħek</td><td>您的 VISA 押金</td><td>租车场景中指退还 VISA 卡预授权/押金</td></tr></tbody></table><h3 id="_7-carmen-客户" tabindex="-1">7. Carmen（客户） <a class="header-anchor" href="#_7-carmen-客户" aria-label="Permalink to &quot;7. Carmen（客户）&quot;">​</a></h3><p><strong>Malti:</strong> Ok, naħseb ikunu xi s-sitta ta&#39; flgħaxija kif nasal.</p><p><strong>整句：</strong> 好的，我想我到的时候大概是晚上六点。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ok</td><td>好的</td><td>借词</td></tr><tr><td>naħseb</td><td>我想</td><td>第一人称单数</td></tr><tr><td>ikunu</td><td>会是</td><td>复数将来（指时间点）</td></tr><tr><td>xi</td><td>大约</td><td>副词</td></tr><tr><td>s-sitta</td><td>六点</td><td><code>is-sitta</code>（六）</td></tr><tr><td>ta&#39; flgħaxija</td><td>晚上的</td><td>原文 <code>flgħaxija</code>，规范拼写 <code>filgħaxija</code></td></tr><tr><td>kif nasal</td><td>当我到达</td><td>kif（当）+nasal（我到达，第一人称单数）</td></tr></tbody></table><h3 id="_8-tal-karozzi-租车公司职员" tabindex="-1">8. Tal-karozzi（租车公司职员） <a class="header-anchor" href="#_8-tal-karozzi-租车公司职员" aria-label="Permalink to &quot;8. Tal-karozzi（租车公司职员）&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb, ikun hawn jien dak il-ħin.</p><p><strong>整句：</strong> 好的，那个时间我会在这里。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tajjeb</td><td>好的</td><td>形容词</td></tr><tr><td>ikun hawn jien</td><td>我会在这里</td><td>ikun（是）+hawn（这里）+jien（我）</td></tr><tr><td>dak il-ħin</td><td>那个时间</td><td>dak（那个）+il-ħin（时间）</td></tr></tbody></table><h3 id="_9-carmen-客户" tabindex="-1">9. Carmen（客户） <a class="header-anchor" href="#_9-carmen-客户" aria-label="Permalink to &quot;9. Carmen（客户）&quot;">​</a></h3><p><strong>Malti:</strong> Sewwa wisq, mela narak il-Ġimgħa fis-sitta ta&#39; flgħaxija. Grazzi!</p><p><strong>整句：</strong> 太好了，那星期五晚上六点见。谢谢！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Sewwa wisq</td><td>太好了</td><td>sewwa（正确）++wisq（非常）</td></tr><tr><td>mela</td><td>那么</td><td>语气词</td></tr><tr><td>narak</td><td>我见到您</td><td><code>nara</code>+<code>-k</code></td></tr><tr><td>il-Ġimgħa</td><td>星期五</td><td>带定冠词</td></tr><tr><td>fis-sitta</td><td>在六点</td><td><code>f&#39;</code>+<code>is-sitta</code></td></tr><tr><td>ta&#39; flgħaxija</td><td>晚上的</td><td>同上（filgħaxija）</td></tr><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr></tbody></table><h3 id="_10-tal-karozzi-租车公司职员" tabindex="-1">10. Tal-karozzi（租车公司职员） <a class="header-anchor" href="#_10-tal-karozzi-租车公司职员" aria-label="Permalink to &quot;10. Tal-karozzi（租车公司职员）&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi lilek, saħħa!</p><p><strong>整句：</strong> 谢谢您，再见！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi lilek</td><td>谢谢您</td><td>grazzi（谢谢）+lilek（给您）</td></tr><tr><td>saħħa</td><td>再见；保重</td><td>字面&quot;健康&quot;，常用告别语</td></tr></tbody></table>',55),o=[i];function n(l,s,h,k,c,g){return d(),a("div",null,o)}const p=t(e,[["render",n]]);export{m as __pageData,p as default};
